BEGIN;CREATE TABLE IF NOT EXISTS safety_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,reporter_identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE RESTRICT,assignment_id uuid REFERENCES work_assignments(id) ON DELETE SET NULL,category text NOT NULL CHECK(category IN('harassment','violence','fraud','discrimination','unsafe_work','other')),description text NOT NULL CHECK(char_length(description) BETWEEN 1 AND 4000),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewing','resolved','dismissed')),created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);ALTER TABLE safety_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE safety_cases FORCE ROW LEVEL SECURITY;CREATE POLICY safety_cases_tenant_isolation ON safety_cases USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON safety_cases TO app_runtime;COMMIT;
